    public Etapa1PercursoOracleTests(ITestOutputHelper output) => _output = output;

    // =========================================================================
    // AC1 — glossario: todas as rulings bloqueadoras estao preenchidas
    // =========================================================================

    /// <summary>
    /// Confirma que o glossario existe e que as quatro rulings bloqueadoras
    /// declaradas no card (BUILTIN-SEMANTICS, CLONE-PRPINTPC, LABEL-CONFLICT,
    /// SCRIPT-HARDCODED) têm campo 'decisao:' nao vazio.
    /// Sem esta garantia, o arnes pode estar validando contra semantica errada.
    /// </summary>
    [Fact]
    public void Glossary_BlockerRulings_AllFourDecisoesFilled()
    {
        Assert.True(File.Exists(GlossaryPath),
            $"Glossario nao encontrado: {GlossaryPath}");

        var yaml = File.ReadAllText(GlossaryPath);

        var requiredRulings = new[]
        {
            "BUILTIN-SEMANTICS",
            "CLONE-PRPINTPC",
            "LABEL-CONFLICT",
            "SCRIPT-HARDCODED",
        };

        foreach (var key in requiredRulings)
        {
            var blockIdx = yaml.IndexOf($"\n  {key}:\n", StringComparison.Ordinal);
            Assert.True(blockIdx >= 0,
                $"Ruling '{key}' nao encontrada no glossario '{GlossaryPath}'.");

            var block = yaml.Substring(blockIdx, Math.Min(2000, yaml.Length - blockIdx));
            var decisaoIdx = block.IndexOf("    decisao:", StringComparison.Ordinal);
            Assert.True(decisaoIdx >= 0,
                $"Ruling '{key}': campo 'decisao:' ausente — ruling nao esta respondida.");

            var after = block.Substring(decisaoIdx + 12).TrimStart();
            var firstLine = after.Split('\n')[0].Trim().Trim('"').Trim('\'');
            Assert.False(string.IsNullOrWhiteSpace(firstLine),
                $"Ruling '{key}': campo 'decisao:' esta vazio — ruling nao ratificada.");

            _output.WriteLine($"[ruling-ok] {key}: {firstLine[..Math.Min(80, firstLine.Length)]}");
        }
    }

