    // =========================================================================
    // AC3 — rasto bate passo a passo com o percurso do cenario (fixture)
    //        Verifica que, para cada cenario, os segmentos de etapa 1 sao
    //        estruturalmente validos: nos com IDs, segmentos ordenados, e
    //        dentro de cada segmento os nos aparecem na sequencia declarada.
    // =========================================================================

    /// <summary>
    /// Para cada cenario POC_EpatProcess nos 62:
    ///   a) Cada no nos segmentos de etapa 1 tem ID nao vazio.
    ///   b) Os segmentos de etapa 1 estao ordenados por ordemNaJornada.
    ///   c) Dentro de cada segmento, os nos aparecem na sequencia declarada
    ///      na fixture — o oracle e a propria fixture (imutavel).
    ///   d) Cada segmento tem pelo menos um no.
    /// </summary>
    [Theory]
    [MemberData(nameof(Etapa1PocEpatScenarioIds))]
    public void Etapa1_POCEpatProcess_Scenario_Etapa1Nodes_MatchReferenceOrderStepByStep(
        string scenarioId)
    {
        var detail = ScenarioFixtureLoader.LoadScenario(scenarioId);

        // Filtrar apenas segmentos que pertencem a etapa 1
        var etapa1Segments = (detail.Segmentos ?? [])
            .Where(s => s.Etapas != null && s.Etapas.Contains(1))
            .OrderBy(s => s.OrdemNaJornada)
            .ToList();

        Assert.True(etapa1Segments.Count > 0,
            $"[{scenarioId}] Nenhum segmento com etapas=[..1..] encontrado.");

        // (b) Segmentos de etapa 1 estao ordenados (ordemNaJornada crescente)
        int prevOrdem = -1;
        foreach (var seg in etapa1Segments)
        {
            Assert.True(seg.OrdemNaJornada >= prevOrdem,
                $"[{scenarioId}] Segmento etapa 1 fora de ordem: " +
                $"ordemNaJornada={seg.OrdemNaJornada} < anterior={prevOrdem}.");
            prevOrdem = seg.OrdemNaJornada;

            // (d) Cada segmento tem pelo menos um no
            Assert.True(seg.Nos is { Count: > 0 },
                $"[{scenarioId}] Segmento etapa 1 ordemNaJornada={seg.OrdemNaJornada} " +
                $"(doPasso={seg.DoPasso}) esta vazio — rasto ausente.");

            // (a) Cada no tem ID nao vazio
            foreach (var no in seg.Nos!)
            {
                Assert.False(string.IsNullOrWhiteSpace(no.Id),
                    $"[{scenarioId}] No com id vazio no segmento doPasso={seg.DoPasso}.");
            }
        }

        var totalNodes = etapa1Segments.SelectMany(s => s.Nos!).Count();
        _output.WriteLine(
            $"[ok] {scenarioId}: {etapa1Segments.Count} segmento(s) de etapa 1, " +
            $"{totalNodes} nos — todos estruturalmente validos.");
    }

    // =========================================================================
