    /// <summary>
    /// Verifica que os 46 cenarios POC_EpatProcess de etapa 1, considerados
    /// em conjunto, cobrem todos os 37 nos do percurso de referencia
    /// SC-POC_EpatProcess-009 (de 'Iniciar Novo Graft' a 'Fim').
    /// Cada no do percurso de referencia deve aparecer no path de pelo menos
    /// um dos cenarios — confirmando que nenhum passo da jornada fica sem
    /// exercicio de oracle.
    /// </summary>
    [Fact]
    public void Etapa1_POCEpatProcess_Coverage_AllReferenceNodesVisitedAcrossScenarios()
    {
        var pocScenarios = Etapa1Scenarios
            .Where(s => s.Process == "POC_EpatProcess")
            .Select(s => ScenarioFixtureLoader.LoadScenario(s.Id))
            .ToList();

        // Todos os nos visitados no path completo de cada cenario
        var coveredNodeIds = pocScenarios
            .SelectMany(d => d.Path ?? [])
            .Select(n => n.Id)
            .ToHashSet();

        var refPath = ReferenceScenario.Path!;
        var missing = refPath.Where(n => !coveredNodeIds.Contains(n.Id)).ToList();

        Assert.Empty(missing);

        _output.WriteLine(
            $"[ok] Todos os {refPath.Count} nos do percurso de referencia cobertos " +
            $"pelos {pocScenarios.Count} cenarios POC_EpatProcess de etapa 1.");
    }

    /// <summary>
    /// Verifica que as datas extremas do segmento declarado no card
    /// (doPasso=1, aoPasso no minimo 1 e existindo cenarios que chegam ao
    /// 'Fim') estao presentes nos segmentos de etapa 1 dos cenarios.
    /// </summary>
    [Fact]
    public void Etapa1_POCEpatProcess_Coverage_IncludesDoPasso1AndFinalNode()
    {
        const string FimId = "_H22mclqWEfG5K7mY0I3I6w";

        var pocScenarios = Etapa1Scenarios
            .Where(s => s.Process == "POC_EpatProcess")
            .Select(s => ScenarioFixtureLoader.LoadScenario(s.Id))
            .ToList();

        // Pelo menos um cenario começa no passo 1 da etapa 1
        var anyStartsAtPasso1 = pocScenarios.Any(d =>
            (d.Segmentos ?? []).Any(s => s.Etapas != null && s.Etapas.Contains(1) && s.DoPasso == 1));

        Assert.True(anyStartsAtPasso1,
            "Nenhum cenario de etapa 1 (POC_EpatProcess) começa no doPasso=1 conforme " +
            "fulfills.segmento do card.");

        // O no 'Fim' aparece no path de pelo menos um cenario etapa 1
        var coveredNodeIds = pocScenarios
            .SelectMany(d => d.Path ?? [])
            .Select(n => n.Id)
            .ToHashSet();

        Assert.True(coveredNodeIds.Contains(FimId),
            $"Nenhum cenario de etapa 1 (POC_EpatProcess) cobre o no 'Fim' (id={FimId}) " +
            $"conforme fechaEm='Fim' do fulfills.segmento do card.");

        _output.WriteLine("[ok] doPasso=1 e no 'Fim' presentes na cobertura da etapa 1.");
    }

    // =========================================================================
    // AC4 — sub-processos da etapa 1 declarados em descidas (DEAT0050, BSCENVPC)
    // =========================================================================

    /// <summary>
    /// Os cenarios de DEAT0050 (4) e BSCENVPC (12) que pertencem a etapa 1
    /// devem estar listados nas descidas do percurso de referencia,
    /// confirmando que as chamadas de sub-processo sao explicitas e nao
    /// inferidas da topologia principal.
    /// </summary>
    [Fact]
    public void Etapa1_SubProcessScenarios_DeclaredInReferenceDescidas()
    {
        var descidas = ReferenceScenario.Descidas ?? [];
        var allDescidaCenarios = descidas
            .SelectMany(d => d.Cenarios ?? [])
            .ToHashSet();

        var subProcessScenarios = Etapa1Scenarios
            .Where(s => s.Process is "DEAT0050" or "BSCENVPC")
            .ToList();

        Assert.True(subProcessScenarios.Count > 0,
            "Nenhum cenario de sub-processo (DEAT0050/BSCENVPC) encontrado nos 62 de etapa 1.");

        foreach (var sub in subProcessScenarios)
        {
            Assert.True(allDescidaCenarios.Contains(sub.Id),
                $"Cenario '{sub.Id}' (processo={sub.Process}) esta nos 62 de etapa 1 " +
                $"mas nao esta declarado em nenhuma descida de {ReferenceScenarioId}. " +
                $"Descidas registadas: [{string.Join(", ", allDescidaCenarios.Take(10))}...]");

            _output.WriteLine($"[ok] {sub.Id} ({sub.Process}) declarado em descidas.");
        }
    }

    /// <summary>
    /// Verifica a contagem por processo nos 62 cenarios de etapa 1:
    /// POC_EpatProcess=46, DEAT0050=4, BSCENVPC=12.
    /// </summary>
    [Fact]
    public void Etapa1_ScenarioCountByProcess_MatchesExpected()
    {
        var byProcess = Etapa1Scenarios
            .GroupBy(s => s.Process)
            .ToDictionary(g => g.Key, g => g.Count());

        Assert.Equal(46, byProcess.GetValueOrDefault("POC_EpatProcess", 0));
        Assert.Equal(4,  byProcess.GetValueOrDefault("DEAT0050", 0));
        Assert.Equal(12, byProcess.GetValueOrDefault("BSCENVPC", 0));

        foreach (var (proc, count) in byProcess.OrderBy(kv => kv.Key))
            _output.WriteLine($"[ok] {proc}: {count} cenarios");
    }
